#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int P, M;
    long long d;
    cin >> P >> M >> d;
    // Provider coordinates grouped by specialty.
    unordered_map<string, vector<pair<long long, long long>>> by;
    for (int i = 0; i < P; i++) {
        string id, spec;
        long long x, y;
        cin >> id >> spec >> x >> y;
        by[spec].push_back({x, y});
    }
    vector<long long> ans;
    for (int i = 0; i < M; i++) {
        long long id, x, y;
        string req;
        cin >> id >> x >> y >> req;
        bool bad = false;
        size_t start = 0;
        while (!bad) {
            size_t bar = req.find('|', start);
            string spec = req.substr(start, bar == string::npos ? string::npos : bar - start);
            // Compare squared distances: exact for integer coordinates, boundary included.
            bool covered = false;
            auto it = by.find(spec);
            if (it != by.end())
                for (auto [a, b] : it->second)
                    if ((a - x) * (a - x) + (b - y) * (b - y) <= d * d) { covered = true; break; }
            if (!covered) bad = true;
            if (bar == string::npos) break;
            start = bar + 1;
        }
        if (bad) ans.push_back(id);
    }
    sort(ans.begin(), ans.end());
    string out;
    for (long long v : ans) out += to_string(v) + "\n";
    cout << (out.empty() ? "\n" : out);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int P = Integer.parseInt(st.nextToken()), M = Integer.parseInt(st.nextToken());
        long d = Long.parseLong(st.nextToken());
        // Provider coordinates grouped by specialty.
        HashMap<String, List<long[]>> by = new HashMap<>();
        for (int i = 0; i < P; i++) {
            st.nextToken();
            String spec = st.nextToken();
            long x = Long.parseLong(st.nextToken()), y = Long.parseLong(st.nextToken());
            by.computeIfAbsent(spec, k -> new ArrayList<>()).add(new long[] {x, y});
        }
        List<Long> ans = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            long id = Long.parseLong(st.nextToken());
            long x = Long.parseLong(st.nextToken()), y = Long.parseLong(st.nextToken());
            String req = st.nextToken();
            boolean bad = false;
            for (String spec : req.split("\\|", -1)) {
                // Compare squared distances: exact for integer coordinates, boundary included.
                boolean covered = false;
                for (long[] p : by.getOrDefault(spec, List.of()))
                    if ((p[0] - x) * (p[0] - x) + (p[1] - y) * (p[1] - y) <= d * d) {
                        covered = true;
                        break;
                    }
                if (!covered) {
                    bad = true;
                    break;
                }
            }
            if (bad) ans.add(id);
        }
        Collections.sort(ans);
        StringBuilder sb = new StringBuilder();
        for (long v : ans) sb.append(v).append('\n');
        System.out.print(sb.length() == 0 ? "\n" : sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var P, M int
	var d int64
	fmt.Fscan(in, &P, &M, &d)
	// Provider coordinates grouped by specialty.
	by := map[string][][2]int64{}
	for i := 0; i < P; i++ {
		var id, spec string
		var x, y int64
		fmt.Fscan(in, &id, &spec, &x, &y)
		by[spec] = append(by[spec], [2]int64{x, y})
	}
	ans := []int64{}
	for i := 0; i < M; i++ {
		var id, x, y int64
		var req string
		fmt.Fscan(in, &id, &x, &y, &req)
		bad := false
		for _, spec := range strings.Split(req, "|") {
			// Compare squared distances: exact for integer coordinates, boundary included.
			covered := false
			for _, p := range by[spec] {
				if (p[0]-x)*(p[0]-x)+(p[1]-y)*(p[1]-y) <= d*d {
					covered = true
					break
				}
			}
			if !covered {
				bad = true
				break
			}
		}
		if bad {
			ans = append(ans, id)
		}
	}
	sort.Slice(ans, func(a, b int) bool { return ans[a] < ans[b] })
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	if len(ans) == 0 {
		w.WriteString("\n")
	}
	for _, v := range ans {
		fmt.Fprintln(w, v)
	}
}
